examples.template:
MonarchCard(elevation: .md) {
    HStack(spacing: theme.spacing.space3) {
        MonarchAvatar(image: nil, name: {{caller}}, isDecorative: true)
        VStack(alignment: .leading, spacing: 2) {
            Text({{caller}})
                .monarchTextStyle(.bodyStrong)
                .foregroundStyle(theme.colors.textDefault)
            Label({{status}}, systemImage: "phone")
                .monarchTextStyle(.caption)
                .foregroundStyle(theme.colors.textMuted)
            Text({{detail}})
                .monarchTextStyle(.caption)
                .foregroundStyle(theme.colors.textMuted)
        }
        Spacer(minLength: 0)
        // The app answers and ends the call through its CXProvider delegate, after CallKit reports it.
        Button {
        } label: {
            // The web draws a phone with a slash (phone-off) for Decline.
            ZStack {
                Image(systemName: "phone.fill")
                Capsule().frame(width: 24, height: 2).rotationEffect(.degrees(-45))
            }
                .foregroundStyle(theme.colors.dangerOnSolid)
                .frame(width: 44, height: 44)
                .background(Circle().fill(theme.colors.dangerSolid))
        }
        .accessibilityLabel("Decline")
        Button {
        } label: {
            Image(systemName: "phone.fill")
                .foregroundStyle(theme.colors.successOnSolid)
                .frame(width: 44, height: 44)
                .background(Circle().fill(theme.colors.successSolid))
        }
        .accessibilityLabel("Answer")
    }
}

